# ---- Global pre‑processing of the whole document ---------------------------------
_motion_logs = {}           # {scope: {object_id: [(frame, x, y, vx, vy, sp), ...]}}
_recorded_end_cache = {}    # {scope: recorded_end}

def _build_motion_logs(doc):
    for node in doc['nodes']:
        if node['kind'] == 'text' and node['title'].startswith('Video '):
            scope = node['title']
            _, _, ml = _get_video_nodes(doc, scope)
            if not ml or ml['kind'] != 'table':
                continue
            logs = defaultdict(list)
            for _, row in table_rows(ml):
                try:
                    frame = int(row['frame'])
                except ValueError:
                    continue
                oid = re.search(r'(\d+)', row['object'])
                if not oid:
                    continue
                oid = oid.group(1)
