                vx, vy = float(row['vx']), float(row['vy'])
                sp = float(row['speed'])
                logs[oid].append((frame, x, y, vx, vy, sp))
            _motion_logs[scope] = {k: v for k, v in logs.items() if v}
            _recorded_end_cache[scope] = max(
                t[0] for traj in _motion_logs[scope].values() for t in traj
            ) if logs else None

