def _get_position_at(traj, frame):
    """Return interpolated (x, y) for a trajectory at integer frame."""
    if frame <= traj[0][0]:
        return traj[0][1], traj[0][2]
    if frame >= traj[-1][0]:
        last = traj[-1]
        dt = frame - last[0]
        return last[1] + last[3] * dt, last[2] + last[4] * dt
    for i in range(len(traj) - 1):
        f0, _, _, _, _, _ = traj[i]
        f1, _, _, _, _, _ = traj[i + 1]
        if f0 <= frame <= f1:
            x0, y0, vx0, vy0 = traj[i][1], traj[i][2], traj[i][3], traj[i][4]
            x1, y1, vx1, vy1 = traj[i + 1][1], traj[i + 1][2], traj[i + 1][3], traj[i + 1][4]
            t = (frame - f0) / (f1 - f0)
            return x0 + (x1 - x0) * t, y0 + (y1 - y0) * t
    return traj[-1][1], traj[-1][2]

