    def add_src(src_list, node_id, idx):
        src_list.append([node_id, idx])

    # Process event lines
    if ev and ev['kind'] == 'list':
        for idx, line in enumerate(ev['lines']):
            frame = _extract_frame(line)
            if frame is None:
                continue
            ids = _extract_object_ids(line)
            txt = line.lower()

            # Decide kind
            if 'in view when the video begins' in txt or 'enters view' in txt:
                kind = 'appear'
                # One input per object in this line
                for oid in ids:
                    src = []
                    add_src(src, ev['node_id'], idx)         # time & id cells
                    if oid in obj_line_map:
                        add_src(src, ob['node_id'], obj_line_map[oid])  # description
                    inv.append({
                        "id": f"input_{scope}_appear_{oid}_{frame}",
                        "time": float(frame),
                        "kind": kind,
                        "entities": [oid],
                        "fields": {"description": obj_desc_map.get(oid, "")},
                        "src": src
                    })
            elif 'exits the scene' in txt:
                kind = 'exit'
                # One outcome per event, but will add to outcomes() too
                # Record as input? not needed
                continue
            elif 'collides with' in txt or 'collides' in txt:
                kind = 'collision'
                continue  # will be outcomes
            else:
                # Unknown line; skip
                continue

    # Note: Exits and collisions are considered outcomes; no input records needed

    return inv


def outcomes(doc, scope):
    """Return list of outcome records (events) for the scope."""
    out = []

    _, ev, _ = _get_video_nodes(doc, scope)

    if ev and ev['kind'] == 'list':
        for idx, line in enumerate(ev['lines']):
            frame = _extract_frame(line)
            if frame is None:
                continue
            ids = _extract_object_ids(line)
            txt = line.lower()

            kind = None
            if 'enters view' in txt or 'in view when the video begins' in txt:
                # Already handled as input
                continue
            if 'exits the scene' in txt:
                kind = 'exit'
            if 'collides with' in txt or 'collides' in txt:
                kind = 'collision'
            if kind is None:
                continue

            src = [[ev['node_id'], idx]]  # need time & entity cells
            out.append({
                "time": float(frame),
                "kind": kind,
                "entities": ids,
                "value": None,
                "src": src
            })

    return out


def params(doc, scope):
    """Return any constants or limits specified in the scope (empty in CLEVRER)."""
    return {}


# ---- step 2: forward model ----
import math
from collections import defaultdict

# ------------------------------------------------------------------
# Global caches for motion logs (populated lazily)
# ------------------------------------------------------------------
_motion_logs = {}          # {scope: {object_id: [(frame, x, y, vx, vy, sp), ...]}}
_recorded_end_cache = {}   # {scope: recorded_end}

def _ensure_logs_for_scope(scope, doc):
    """Load motion logs for a single scope if not already cached."""
    if scope in _motion_logs:
        return
    _, _, ml = _get_video_nodes(doc, scope)
    if not ml or ml['kind'] != 'table':
        _motion_logs[scope] = {}
        _recorded_end_cache[scope] = None
        return
    logs = defaultdict(list)
    for _, row in table_rows(ml):
        try:
            frame = int(row['frame'])
        except ValueError:
            continue
        m = re.search(r'(\d+)', row['object'])
        if not m:
            continue
        oid = m.group(1)
        x, y = float(row['x']), float(row['y'])
        vx, vy = float(row['vx']), float(row['vy'])
        sp = float(row['speed'])
        logs[oid].append((frame, x, y, vx, vy, sp))
    _motion_logs[scope] = {k: v for k, v in logs.items() if v}
    if logs:
        _recorded_end_cache[scope] = max(
            t[0] for traj in _motion_logs[scope].values() for t in traj
        )
    else:
        _recorded_end_cache[scope] = None

def _recorded_end(scope):
    return _recorded_end_cache.get(scope)

# ------------------------------------------------------------------
# Utility: interpolate position at arbitrary time
# ------------------------------------------------------------------
def _position_at(traj, t):
    """Get interpolated (x, y) and velocity at time t (float)."""
    if t <= traj[0][0]:
        return traj[0][1], traj[0][2], traj[0][3], traj[0][4]
    if t >= traj[-1][0]:
        last = traj[-1]
        dt = t - last[0]
        return last[1] + last[3]*dt, last[2] + last[4]*dt, last[3], last[4]
    for i in range(len(traj)-1):
        f0, x0, y0, vx0, vy0, _ = traj[i]
        f1, x1, y1, vx1, vy1, _ = traj[i+1]
        if f0 <= t <= f1:
            ratio = (t - f0)/(f1 - f0)
            x = x0 + (x1-x0)*ratio
            y = y0 + (y1-y0)*ratio
            # use velocity from the later frame as approximate instantaneous
            return x, y, vx1, vy1
    return traj[-1][1], traj[-1][2], traj[-1][3], traj[-1][4]

# ------------------------------------------------------------------
# Collision distance threshold (empirical)
# ------------------------------------------------------------------
def _collision_dist():
    return 0.22  # slightly above max observed inter‑object distance

# ------------------------------------------------------------------
# Main simulation -----------------------------------------------
# ------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Predict collision and exit outcomes for the given video scope.
    Only objects that have an 'appear' input are considered.
    """
    _ensure_logs_for_scope(scope, doc)

    # collect appeared objects
    appear_objs = {}
    for inp in inputs:
        if inp.get('kind') == 'appear':
            for oid in inp.get('entities', []):
                t = float(inp.get('time', 0.0))
                appear_objs[oid] = min(appear_objs.get(oid, math.inf), t)

    if not appear_objs:
        return []

    # get trajectories for these objects (only if they exist)
    traj_map = {oid: _motion_logs[scope][oid] for oid in appear_objs if oid in _motion_logs[scope]}

    rec_end = _recorded_end(scope)
    if start is None:
        start = 0.0 if rec_end is None else float(rec_end)
    if horizon is None:
        horizon = float(rec_end) if rec_end is not None else start

    start_frame, horizon_frame = math.ceil(start), math.floor(horizon)

    # ------------------------------------------------------------------
    # 1. Predict exit events: time of last frame in the recorded motion log
    # ------------------------------------------------------------------
    outcomes = []
    for oid, traj in traj_map.items():
        last_frame = traj[-1][0]
        if last_frame < horizon_frame:
            outcomes.append({
                "time": float(last_frame),
                "kind": "exit",
                "entities": [oid],
                "value": None,
                "src": [["unknown", 0]]
            })

    # ------------------------------------------------------------------
    # 2. Predict collision events
    # ------------------------------------------------------------------
    coll_thr = _collision_dist()
    seen_pairs = set()

    active_objs = list(traj_map.keys())
    for i in range(len(active_objs)):
        for j in range(i+1, len(active_objs)):
            a, b = active_objs[i], active_objs[j]
            # skip if one appears after the other starts, but we already consider only appear objs
            # get start positions and velocities at start_frame
            pa_x, pa_y, va_x, va_y = _position_at(traj_map[a], start_frame)
            pb_x, pb_y, vb_x, vb_y = _position_at(traj_map[b], start_frame)
            rx0, ry0 = pa_x - pb_x, pa_y - pb_y
            rvx, rvy = va_x - vb_x, va_y - vb_y

            # quadratic: |r0 + v t|^2 = thr^2
            A = rvx**2 + rvy**2
            B = 2*(rx0*rvx + ry0*rvy)
            C = rx0**2 + ry0**2 - coll_thr**2

            if A == 0:
                if C <= 0:
                    t_col = 0.0
                else:
                    continue
            else:
                disc = B**2 - 4*A*C
                if disc < 0:
                    continue
                sqrt_disc = math.sqrt(disc)
                t1 = (-B - sqrt_disc)/(2*A)
                t2 = (-B + sqrt_disc)/(2*A)
                t_col = None
                for t in sorted([t1, t2]):
                    if t >= 0:
                        t_col = t
                        break
                if t_col is None:
                    continue
            time_of_collision = start_frame + t_col
            if time_of_collision > horizon_frame:
                continue
            coll_time_int = int(round(time_of_collision))
            # ensure within bounds
            if start_frame <= coll_time_int <= horizon_frame:
                pair = frozenset([a, b])
                if pair in seen_pairs:
                    continue
                seen_pairs.add(pair)
                outcomes.append({
                    "time": float(coll_time_int),
                    "kind": "collision",
                    "entities": [a, b],
                    "value": None,
                    "src": [["unknown", 0]]
                })

    outcomes.sort(key=lambda o: o["time"])
    return outcomes
